4495, ["name"] = "Bossman Toof", ["note"] = "North-east end of the large wooden bridge: two centurions at the bridge start his fight; kill his shamans first; not in the game's boss list, tick him off by hand"}, {["kind"] = "boss", ["floor"] = 1030391, ["x"] = 0.6797, ["y"] = 0.1523, ["name"] = "Overseer Mugg", ["note"] = "Called Overlord Mugg in the game; last boss, in the large hall at the top; kill his two centurions first; he leaps at three players, so spread out"}}, ["source"] = "ForeverDungeonRoutes", ["entrance"] = {["zone"] = "Riverglades", ["note"] = "Bolder'ok area"}}, ["uldaman"] = {["floors"] = {{["id"] = 230, ["name"] = "Hall of the Keepers", ["tiles"] = {448430, 448434, 448435, 448436, 448437, 448438, 448439, 448440, 448441, 448431, 448432, 448433}}, {["id"] = 231, ["name"] = "Khaz'Goroth's Seat", ["tiles"] = {448442, 448446, 448447, 448448, 448449, 448450, 448451, 448452, 448453, 448443, 448444, 448445}}}, ["markers"] = {{["kind"] = "boss", ["floor"] = 230, ["x"] = 0.5838, ["y"] = 0.9217, ["name"] = "The Lost Dwarves", ["note"] = "Baelog, Eric and Olaf fight together (friendly to the Alliance). Baelog's chest holds the Gni'kiv Medallion for Ironaya"}, {["kind"] = "boss", ["floor"] = 230, ["x"] = 0.5339, ["y"] = 0.7242, ["name"] = "Revelosh", ["note"] = "Drops the Shaft of Tsol, half of the staff that summons Ironaya: make sure to loot it"}, {["kind"] = "boss", ["floor"] = 230, ["x"] = 0.3703, ["y"] = 0.7347, ["name"] = "Ironaya", ["note"] = "Combine the Shaft of Tsol (Revelosh) and the Gni'kiv Medallion (Baelog's chest) into the Staff of Prehistoria and use it in the Map Chamber to summon her"}, {["kind"] = "boss", ["floor"] = 230, ["x"] = 0.2894, ["y"] = 0.6, ["name"] = "Obsidian Sentinel", ["note"] = "Splits off Obsidian Shards during the fight: kill each shard as soon as it appears"}, {["kind"] = "boss", ["floor"] = 230, ["x"] = 0.477, ["y"] = 0.4429, ["name"] = "Ancient Stone Keeper"}, {["kind"] = "boss", ["floor"] = 230, ["x"] = 0.2655, ["y"] = 0.